MDIR=/AI4M/users/Axel/LeanAlgebraicGeometry-Horizon/.lake-packages/mathlib
grep -rn "height_map\b\|height_comap\b" $MDIR/Mathlib/RingTheory/ | grep -v "\.olean" | head -8
echo ===JacobsonMv===
grep -rn "instance.*IsJacobsonRing\|isJacobsonRing" $MDIR/Mathlib/RingTheory/Jacobson/Ring.lean | tail -8
echo ===AtPrimeDim===
grep -rn "ringKrullDim_eq_height\|height.*ringKrullDim" $MDIR/Mathlib/RingTheory/KrullDimension/LocalRing.lean $MDIR/Mathlib/RingTheory/KrullDimension/Basic.lean 2>/dev/null | head -8
echo ===spanFinrankCot===
grep -rn "spanFinrank_maximalIdeal_eq_finrank_cotangentSpace" $MDIR/Mathlib/ | grep -v olean | head -3

MDIR=/AI4M/users/Axel/LeanAlgebraicGeometry-Horizon/.lake-packages/mathlib
echo ===Jacobson-instances===
grep -rn "instance.*MvPolynomial\|MvPolynomial.*IsJacobsonRing" $MDIR/Mathlib/RingTheory/Jacobson/Ring.lean | head -5
echo ===maximalIdeal_height===
grep -rn "maximalIdeal_height_eq_ringKrullDim\|localization.*height\|AtPrime.*ringKrullDim" $MDIR/Mathlib/RingTheory/Ideal/Height.lean $MDIR/Mathlib/RingTheory/KrullDimension/*.lean 2>/dev/null | head -8
echo ===StandardSmoothDef===
sed -n '/class IsStandardSmooth/,/^$/p' $MDIR/Mathlib/RingTheory/Smooth/StandardSmooth.lean | head -30
grep -n "dimension" $MDIR/Mathlib/RingTheory/Smooth/StandardSmooth.lean | head -20

MDIR=/AI4M/users/Axel/LeanAlgebraicGeometry-Horizon/.lake-packages/mathlib
grep -n "def dimension\|dimension :=" $MDIR/Mathlib/RingTheory/Presentation.lean | head; sed -n '/def dimension/,+8p' $MDIR/Mathlib/RingTheory/Presentation.lean | head -12
echo ===Generators===
grep -n "def ker\|ker :\|algebraMap_surjective\|quotientEquiv\|aeval_val" $MDIR/Mathlib/RingTheory/Generators.lean | head -15
echo ===Presentation-fields===
sed -n '/structure Presentation/,/^end/p' $MDIR/Mathlib/RingTheory/Presentation.lean | head -25

MDIR=/AI4M/users/Axel/LeanAlgebraicGeometry-Horizon/.lake-packages/mathlib
ls $MDIR/Mathlib/RingTheory/Extension/
echo ===dimension-def===
grep -n "def dimension" $MDIR/Mathlib/RingTheory/Extension/Presentation/Basic.lean; sed -n "$(grep -n 'def dimension' $MDIR/Mathlib/RingTheory/Extension/Presentation/Basic.lean | cut -d: -f1),+10p" $MDIR/Mathlib/RingTheory/Extension/Presentation/Basic.lean
echo ===Generators-ker===
grep -n "def ker\|abbrev Ring\|algebraMap_surjective\|def val\|quotientEquiv" $MDIR/Mathlib/RingTheory/Extension/Generators.lean | head

MDIR=/AI4M/users/Axel/LeanAlgebraicGeometry-Horizon/.lake-packages/mathlib
echo ===Generators-algebra-ker===
grep -n "instance\|def ker\|noncomputable def\|abbrev" $MDIR/Mathlib/RingTheory/Extension/Generators.lean | sed -n '1,25p'
echo ===ker-def===
sed -n "$(grep -n 'ker' $MDIR/Mathlib/RingTheory/Extension/Generators.lean | grep 'def\|abbrev' | head -1 | cut -d: -f1),+6p" $MDIR/Mathlib/RingTheory/Extension/Generators.lean
echo ===variables-heights===
sed -n '36,48p' $MDIR/Mathlib/RingTheory/Ideal/KrullsHeightTheorem.lean
echo ===AtPrime-sig===
sed -n '398,406p' $MDIR/Mathlib/RingTheory/Ideal/Height.lean
